INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-x112-lynx', 1, 'NG-X112 "Big Bang" Over and Under Assault Rifle (handheld)', 'Particle beam (over) 6D6+6 M.D. per shot. Grenade launcher (under) by grenade: fragmentation 3D6 M.D. to a 12 ft (3.7 m) radius; high explosive/armor piercing 4D6 M.D. to 3 ft (0.9 m); plasma 6D6 M.D. to 5 ft (1.5 m); smoke fills a 40 ft (12.2 m) radius; tear gas a 25 ft (7.6 m) radius, -10 to strike, parry and dodge, -3 initiative and one fewer attack while in it and 1D6+1 rounds after, unless protected; stun/flash a 4 ft (1.2 m) radius, -10 to strike, parry and dodge, -1 initiative and one fewer attack for 1D4 rounds', 1, '1,200 ft (366 m) for both barrels', 'Particle beam single shots; grenades one at a time; each shot is one melee attack', 'Particle beam effectively unlimited on a UEL, or 6 blasts per standard E-Clip; the grenade tube takes 10, then must be hand loaded. An M.D.C. case holds 24 more; loads may be one type or a mix of 2-5, riot loads being tear gas, stun/flash and smoke only', NULL, 'Anti-monster and anti-armor, secondarily assault and wall breaching. A big experimental two-barrel rifle for power armor and Combat Cyborgs, for now issued only with the Lynx, the Cougar and (optionally) the Enforcer Guardsman, though NG expects to widen sales. A precision particle beam over a pump-action grenade launcher, with a removable sling. Hex grenades are an option against Xiticix and monsters (described in Northern Gun One).'),
  ('ng-x112-lynx', 2, 'NG-X12 Shoulder Grenade Launchers (2)', 'By grenade type; high explosive and plasma against Xiticix and armor, smoke, tear gas and stun/flash for riots (two of each plus two fragmentation or plasma is the recommended mix)', 1, '1,000 ft (printed as 305 km; 305 m)', 'One at a time or volleys of 2 or 4', '8 total, four per launcher', NULL, 'Assault and anti-personnel, secondarily defense and riot control. Each launcher sits in a housing where the neck meets a shoulder.'),
  ('ng-x112-lynx', 3, 'Left Forearm Ion Blasters (2)', '3D6 M.D. per blast; 6D6 M.D. per double blast at one target', 1, '1,000 ft (305 m)', 'Each single or double blast is one melee attack', 'Effectively unlimited', NULL, 'Assault and anti-personnel, secondarily defense. A short-range pair mounted in the left forearm, aimed by pointing the arm.'),
  ('ng-x112-lynx', 4, 'Left Forearm Vibro-Blades (2)', '2D6 M.D. per slash with both blades; 1D6 with one', 1, 'Arm''s reach; melee', NULL, NULL, NULL, 'Assault and anti-personnel, secondarily defense. Twin blades set between the two ion blasters that can point forward, back, straight up or lie flat out of sight.'),
  ('ng-x39-mantis', 1, 'Vibro-Mantis Blades (2)', 'Robot P.S. 30 included: restrained slash 1D6 M.D.; full slash 3D6; double slash with both blades 6D6 (two attacks); full stab or chop 4D6; double stab 1D4x10+2 (two attacks, no parry next action); power stab with one blade 1D4x10+6 (two attacks, no parry next action; never with both); leap strike slash 4D6; spinning leap strike 5D6; power stabbing leap strike 1D6x10+3 (three attacks, no parry next action); scissor strike/pin 3D6, the caught limb or barrel held until released or cut off, each tug 1D6 (3D6 pulling hard) and 3D6 to anyone gripping the edge; lock grip, latched on, each shake or pull 1D6 to what it holds (a hard shake 3D6 with a 01-35% chance to throw it off)', 1, '3-4 ft (0.9 to 1.2 m) beyond arm''s reach, by blade position', 'Per hand to hand attacks', NULL, NULL, 'Assault and anti-armor, secondarily sabotage and climbing. Two 4 ft (1.2 m) scythe Vibro-Blades, edged on both sides and serrated on the inner edge, braced by hydraulics; they climb walls and ceilings like picks and, given time, cut through hive walls, bunkers, hatches and hulls. The signature move is the praying mantis leap: dropping onto, in front of or behind a giant robot to stab or slash its head, shoulders, weapons or sensors.'),
  ('ng-x39-mantis', 2, 'NG-L133 Head Laser', '2D6 M.D. per shot', 1, '1,200 ft (366 m)', 'Each blast is one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 70 blasts per charge on the electric battery version', NULL, 'Cutting and anti-weapon systems, secondarily anti-personnel, assault and defense. A light hands-free laser on the crown of the helmet for picking off sensors, cameras and guns.'),
  ('ng-x39-mantis', 3, 'NG-I233 Ion-Pulse Blaster', '3D6 M.D. per shot', 1, '1,000 ft (305 m)', 'Each blast is one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 45 blasts per charge on the electric battery version, plus 10 from its E-Clip port', NULL, 'Cutting and anti-weapon systems, secondarily anti-personnel, assault and defense. Hidden in the left armored shoulder housing; fires forward only, through a 45 degree up and down arc.'),
  ('ng-x39-mantis', 4, 'NG-PL333 Plasma Ejector', '5D6 M.D. per blast', 1, '100 ft (30.5 m)', 'Each blast is one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 15 blasts per charge on the electric battery version, which also has three E-Clip ports (5 blasts per clip)', NULL, 'Cutting and anti-weapon systems, secondarily anti-personnel, assault and defense. Hidden in the right armored shoulder housing; turns 360 degrees with a 20 degree up and down arc. One to three blasts wreck most sensor clusters, cameras and small turrets, and the heat works on monsters and animals that fear fire, or as a surprise at point-blank range in a grapple.'),
  ('ng-mru876-med-rec-white-knight', 1, 'G-876 Shoulder Mounted Grenade Launcher', 'By grenade type; usually six smoke, three high explosive and three plasma, but any Northern Gun grenade fits', 1, '1,000 ft (305 m); smoke has a 30 ft (9.1 m) minimum', 'One at a time', '12 total in four magazines; the pilot switches among up to three loads by voice', NULL, 'Marking evacuation zones, secondarily cover and defense. A rapid-fire launcher on the right shoulder that turns 360 degrees with a 45 degree up and down arc.'),
  ('ng-mru876-med-rec-white-knight', 2, 'Jaws of Life (right forearm)', '2D6+4 M.D. spreading, prying or tearing (Robot P.S. 40; not for punches)', 1, 'Touch; close combat', NULL, 'Effectively unlimited', NULL, 'Rescue and forced entry, secondarily anti-fortification. A hydraulic spreader with Vibro-Blade tips that opens hatches and vehicle doors, tears through wreckage and cuts pilots out of damaged armor, yet can lift the injured gently; a weapon only in an emergency. Its housing also holds a laser scalpel, a pair of plain scalpels (1D6 S.D.C.) and basic repair tools.'),
  ('ng-mru876-med-rec-white-knight', 3, 'Laser Torch (left forearm)', 'Settings of 1D6, 2D6, 4D6 or 1D4x10 S.D.C., 1 M.D. or 1D4 M.D.', 1, '40 ft (12.2 m)', 'Each blast is one melee attack/action', 'Effectively unlimited on a UEL; one hour of battery off the arm, recharged in its housing', NULL, 'Cutting and rescue, secondarily defense. A precision cutter on top of the medical scanner for freeing trapped people and cutting armor away from wounds; fires from the arm or comes off as a hand tool.'),
